@code {
    private string activeSection = "Profile";
    private bool loading = true;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private UserProfile? savedProfile;
    private UserProfile? editProfile;
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";

    // Notifications state
    private NotificationPrefs? savedNotifPrefs;
    private bool notifEmailEnabled;
    private bool notifPushEnabled;
    private bool notifWeeklyDigest;
    private Dictionary<string, bool>? channelMuteStates;

    // Security state
    private SecuritySettings? securitySettings;
    private bool twoFactorEnabled;
    private bool passwordPanelExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private AppearanceSettings? savedAppearance;
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        loading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    editProfile = savedProfile;
                    profileDisplayName = savedProfile.DisplayName;
                    profileEmail = savedProfile.Email;
                    profileBio = savedProfile.Bio;
                    break;
                case "Notifications":
                    savedNotifPrefs = await SettingsService.GetNotificationPrefsAsync();
                    notifEmailEnabled = savedNotifPrefs.EmailNotifications;
                    notifPushEnabled = savedNotifPrefs.PushNotifications;
                    notifWeeklyDigest = savedNotifPrefs.WeeklyDigest;
                    channelMuteStates = savedNotifPrefs.MutedChannels.ToDictionary(c => c, _ => true);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
                    passwordPanelExpanded = false;
                    currentPassword = "";
                    newPassword = "";
                    confirmPassword = "";
                    break;
                case "Appearance":
                    savedAppearance = await SettingsService.GetAppearanceAsync();
                    appearanceTheme = savedAppearance.Theme;
                    appearanceFontSize = savedAppearance.FontSize;
                    appearanceLanguage = savedAppearance.Language;
                    appearanceCompactMode = savedAppearance.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", "error");
        }
        finally
        {
            loading = false;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var updated = new UserProfile(profileDisplayName, profileEmail, editProfile!.AvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        editProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
            editProfile = savedProfile;
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileBio = savedProfile.Bio;
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private void ToggleChannel(string channel, bool muted)
    {
        if (channelMuteStates != null)
            channelMuteStates[channel] = muted;
    }

    private async Task SaveNotifications()
    {
        var mutedChannels = channelMuteStates?
            .Where(c => c.Value)
            .Select(c => c.Key)
            .ToList() ?? new List<string>();

        var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        savedNotifPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => passwordPanelExpanded = !passwordPanelExpanded;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword) || string.IsNullOrWhiteSpace(currentPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelExpanded = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Password update failed: {ex.Message}", "error");
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewFontSize() => appearanceFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.25rem",
        _ => "1rem"
    };

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        savedAppearance = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helpers
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => toastMessage = null;
}
"}

