+}
+
+@* ===== SECURITY SECTION ===== *@
+@code {
+    private RenderFragment SecuritySection => __builder =>
+    {
+        <section class="settings-section">
+            <h2>Security</h2>
+
+            <div class="expandable-panel">
+                <button class="panel-header" @onclick="TogglePasswordPanel">
+                    <span>Change Password</span>
+                    <span class="expand-icon">@(passwordPanelExpanded ? "▼" : "▶")</span>
+                </button>
+                @if (passwordPanelExpanded)
+                {
+                    <div class="panel-body">
+                        <div class="form-group">
+                            <label for="currentPassword">Current Password</label>
+                            <input id="currentPassword" type="password" @bind="currentPassword" />
+                        </div>
+                        <div class="form-group">
+                            <label for="newPassword">New Password</label>
+                            <input id="newPassword" type="password" @bind="newPassword" />
+                        </div>
+                        <div class="form-group">
+                            <label for="confirmPassword">Confirm Password</label>
+                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
+                        </div>
+                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
+                    </div>
+                }
+            </div>
+
+            <div class="security-item">
+                <div class="tfa-row">
+                    <span>Two-Factor Authentication</span>
+                    <span class="status-indicator @(twoFactorEnabled ? "status-on" : "status-off")">
+                        @(twoFactorEnabled ? "Enabled" : "Disabled")
+                    </span>
+                </div>
+                @if (securitySettings?.LastPasswordChange.HasValue == true)
+                {
+                    <p class="text-muted">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
+                }
+            </div>
+
+            <h3>Active Sessions</h3>
+            <table class="sessions-table">
+                <thead>
+                    <tr>
+                        <th>Device</th>
+                        <th>Location</th>
+                        <th>Last Active</th>
+                        <th></th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @if (securitySettings?.Sessions != null)
+                    {
+                        @foreach (var session in securitySettings.Sessions)
+                        {
+                            <tr>
+                                <td>@session.Device</td>
+                                <td>@session.Location</td>
+                                <td>@session.LastActive.ToString("g")</td>
+                                <td>
+                                    @if (session != securitySettings.Sessions.FirstOrDefault())
+                                    {
+                                        <button class="btn btn-danger btn-sm"
+                                                @onclick="() => ConfirmRevokeSession(session)">
+                                            Revoke
+                                        </button>
+                                    }
+                                    else
+                                    {
+                                        <span class="badge">Current</span>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    }
+                </tbody>
+            </table>
+
+            @if (showRevokeConfirmation)
+            {
+                <div class="modal-overlay" @onclick="CancelRevoke">
+                    <div class="modal-dialog" @onclick:stopPropagation="true">
+                        <h4>Confirm Session Revocation</h4>
+                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
+                        <div class="button-group">
+                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
+                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                        </div>
+                    </div>
+                </div>
+            }
+        </section>
+    };
+}
+
+@* ===== APPEARANCE SECTION ===== *@
+@code {
+    private RenderFragment AppearanceSection => __builder =>
+    {
+        <section class="settings-section">
+            <h2>Appearance</h2>
+
+            <div class="form-group">
+                <label>Theme</label>
+                <div class="radio-group">
+                    <label><input type="radio" name="theme" value="Light" checked="@(appearanceTheme == "Light")" @onchange='() => appearanceTheme = "Light"' /> Light</label>
+                    <label><input type="radio" name="theme" value="Dark" checked="@(appearanceTheme == "Dark")" @onchange='() => appearanceTheme = "Dark"' /> Dark</label>
+                    <label><input type="radio" name="theme" value="System" checked="@(appearanceTheme == "System")" @onchange='() => appearanceTheme = "System"' /> System</label>
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label>Font Size</label>
+                <div class="radio-group">
+                    <label><input type="radio" name="fontSize" value="Small" checked="@(appearanceFontSize == "Small")" @onchange='() => appearanceFontSize = "Small"' /> Small</label>
+                    <label><input type="radio" name="fontSize" value="Medium" checked="@(appearanceFontSize == "Medium")" @onchange='() => appearanceFontSize = "Medium"' /> Medium</label>
+                    <label><input type="radio" name="fontSize" value="Large" checked="@(appearanceFontSize == "Large")" @onchange='() => appearanceFontSize = "Large"' /> Large</label>
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label for="language">Language</label>
+                <select id="language" @bind="appearanceLanguage">
+                    <option value="en">English</option>
+                    <option value="es">Español</option>
+                    <option value="fr">Français</option>
+                    <option value="de">Deutsch</option>
+                    <option value="ja">日本語</option>
+                    <option value="zh">中文</option>
+                </select>
+            </div>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <input type="checkbox" @bind="appearanceCompactMode" />
+                    <span>Compact Mode</span>
+                </label>
+            </div>
+
+            <div class="live-preview @(appearanceTheme == "Dark" ? "preview-dark" : "preview-light")"
+                 style="font-size: @GetPreviewFontSize();">
+                <h4>Live Preview</h4>
+                <p class="@(appearanceCompactMode ? "compact" : "")">
+                    This is a preview of your selected appearance settings.
+                    The theme is <strong>@appearanceTheme</strong>, font size is <strong>@appearanceFontSize</strong>,
+                    and compact mode is <strong>@(appearanceCompactMode ? "on" : "off")</strong>.
+                </p>
+                <div class="preview-elements">
+                    <button class="btn btn-primary btn-preview">Sample Button</button>
+                    <span class="preview-badge">Badge</span>
+                </div>
+            </div>
+
+            <div class="button-group">
+                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
+            </div>
+        </section>
+    };
+}
+
+@code {
+    private string activeSection = "Profile";
+    private bool loading = true;
+    private string? toastMessage;
+    private string toastType = "success";
+
+    // Profile state
+    private UserProfile? savedProfile;
+    private UserProfile? editProfile;
+    private string profileDisplayName = "";
+    private string profileEmail = "";
+    private string profileBio = "";
+
+    // Notifications state
+    private NotificationPrefs? savedNotifPrefs;
+    private bool notifEmailEnabled;
+    private bool notifPushEnabled;
+    private bool notifWeeklyDigest;
+    private Dictionary<string, bool>? channelMuteStates;
+
+    // Security state
+    private SecuritySettings? securitySettings;
+    private bool twoFactorEnabled;
+    private bool passwordPanelExpanded;
+    private string currentPassword = "";
+    private string newPassword = "";
+    private string confirmPassword = "";
+    private bool showRevokeConfirmation;
+    private ActiveSession? sessionToRevoke;
+
+    // Appearance state
+    private AppearanceSettings? savedAppearance;
+    private string appearanceTheme = "System";
+    private string appearanceFontSize = "Medium";
+    private string appearanceLanguage = "en";
+    private bool appearanceCompactMode;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadSectionData();
+    }
+
+    private async Task SetSection(string section)
+    {
+        activeSection = section;
+        loading = true;
+        await LoadSectionData();
+    }
+
+    private async Task LoadSectionData()
+    {
+        try
+        {
+            switch (activeSection)
+            {
+                case "Profile":
+                    savedProfile = await SettingsService.GetProfileAsync();
+                    editProfile = savedProfile;
+                    profileDisplayName = savedProfile.DisplayName;
+                    profileEmail = savedProfile.Email;
+                    profileBio = savedProfile.Bio;
+                    break;
+                case "Notifications":
+                    savedNotifPrefs = await SettingsService.GetNotificationPrefsAsync();
+                    notifEmailEnabled = savedNotifPrefs.EmailNotifications;
+                    notifPushEnabled = savedNotifPrefs.PushNotifications;
+                    notifWeeklyDigest = savedNotifPrefs.WeeklyDigest;
+                    channelMuteStates = savedNotifPrefs.MutedChannels.ToDictionary(c => c, _ => true);
+                    break;
+                case "Security":
+                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
+                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
+                    passwordPanelExpanded = false;
+                    currentPassword = "";
+                    newPassword = "";
+                    confirmPassword = "";
+                    break;
+                case "Appearance":
+                    savedAppearance = await SettingsService.GetAppearanceAsync();
+                    appearanceTheme = savedAppearance.Theme;
+                    appearanceFontSize = savedAppearance.FontSize;
+                    appearanceLanguage = savedAppearance.Language;
+                    appearanceCompactMode = savedAppearance.CompactMode;
+                    break;
+            }
+        }
+        catch (Exception ex)
+        {
+            ShowToast($"Error loading settings: {ex.Message}", "error");
+        }
+        finally
+        {
+            loading = false;
+        }
+    }
+
+    // Profile methods
+    private async Task SaveProfile()
+    {
+        var updated = new UserProfile(profileDisplayName, profileEmail, editProfile!.AvatarUrl, profileBio);
+        await SettingsService.SaveProfileAsync(updated);
+        savedProfile = updated;
+        editProfile = updated;
+        ShowToast("Profile saved successfully!", "success");
+    }
+
+    private void DiscardProfileChanges()
+    {
+        if (savedProfile is not null)
+        {
+            editProfile = savedProfile;
+            profileDisplayName = savedProfile.DisplayName;
+            profileEmail = savedProfile.Email;
+            profileBio = savedProfile.Bio;
+        }
+        ShowToast("Changes discarded.", "info");
+    }
+
+    // Notifications methods
+    private void ToggleChannel(string channel, bool muted)
+    {
+        if (channelMuteStates != null)
+            channelMuteStates[channel] = muted;
+    }
+
+    private async Task SaveNotifications()
+    {
+        var mutedChannels = channelMuteStates?
+            .Where(c => c.Value)
+            .Select(c => c.Key)
+            .ToList() ?? new List<string>();
+
+        var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, mutedChannels);
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        savedNotifPrefs = prefs;
+        ShowToast("Notification preferences saved!", "success");
+    }
+
+    // Security methods
+    private void TogglePasswordPanel() => passwordPanelExpanded = !passwordPanelExpanded;
+
+    private async Task UpdatePassword()
+    {
+        if (string.IsNullOrWhiteSpace(newPassword) || string.IsNullOrWhiteSpace(currentPassword))
+        {
+            ShowToast("Please fill in all password fields.", "error");
+            return;
+        }
+        if (newPassword != confirmPassword)
+        {
+            ShowToast("New password and confirmation do not match.", "error");
+            return;
+        }
+
+        try
+        {
+            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
+            currentPassword = "";
+            newPassword = "";
+            confirmPassword = "";
+            passwordPanelExpanded = false;
+            ShowToast("Password updated successfully!", "success");
+        }
+        catch (Exception ex)
+        {
+            ShowToast($"Password update failed: {ex.Message}", "error");
+        }
+    }
+
+    private void ConfirmRevokeSession(ActiveSession session)
+    {
+        sessionToRevoke = session;
+        showRevokeConfirmation = true;
+    }
+
+    private void CancelRevoke()
+    {
+        sessionToRevoke = null;
+        showRevokeConfirmation = false;
+    }
+
+    private async Task RevokeSession()
+    {
+        if (sessionToRevoke is not null)
+        {
+            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
+            securitySettings = await SettingsService.GetSecuritySettingsAsync();
+            ShowToast("Session revoked.", "success");
+        }
+        showRevokeConfirmation = false;
+        sessionToRevoke = null;
+    }
+
+    // Appearance methods
+    private string GetPreviewFontSize() => appearanceFontSize switch
+    {
+        "Small" => "0.85rem",
+        "Large" => "1.25rem",
+        _ => "1rem"
+    };
+
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        savedAppearance = settings;
+        ShowToast("Appearance settings saved!", "success");
+    }
+
+    // Toast helpers
+    private void ShowToast(string message, string type)
+    {
+        toastMessage = message;
+        toastType = type;
+        _ = DismissToastAfterDelay();
+    }
+
+    private async Task DismissToastAfterDelay()
+    {
+        await Task.Delay(3000);
+        toastMessage = null;
+        await InvokeAsync(StateHasChanged);
+    }
+
+    private void DismissToast() => toastMessage = null;
+}
+

arguments.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: background 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    color: #555;
}

.settings-sidebar li:hover {
    background: #e9ecef;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #555;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #444;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-group select {
    max-width: 300px;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: opacity 0.2s;
}

.btn:hover {
    opacity: 0.85;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-danger {
    background: #d32f2f;
    color: white;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f5f5f5;
    border-radius: 8px;
}

.avatar-img {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #ddd;
}

.avatar-placeholder {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #ddd;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    color: #777;
}

.avatar-url {
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    margin-bottom: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.5rem 0;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.75rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Security items */
.security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 6px;
}

.tfa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-weight: 500;
}

.status-indicator {
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-on {
    background: #c8e6c9;
    color: #2e7d32;
}

.status-off {
    background: #ffcdd2;
    color: #c62828;
}

.text-muted {
    color: #888;
    font-size: 0.85rem;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    color: #555;
}

.badge {
    padding: 0.2rem 0.5rem;
    background: #e3f2fd;
    color: #1976d2;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin-top: 0;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-weight: normal;
}

/* Live preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
    transition: all 0.3s;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.preview-light {
    background: #ffffff;
    color: #333;
}

.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .btn-preview {
    background: #64b5f6;
}

.preview-elements {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-top: 0.75rem;
}

.btn-preview {
    padding: 0.4rem 1rem;
    border: none;
    border-radius: 4px;
    background: #1976d2;
    color: white;
    font-size: inherit;
}

.preview-badge {
    padding: 0.2rem 0.6rem;
    background: #e3f2fd;
    color: #1976d2;
    border-radius: 4px;
    font-size: 0.85em;
}

.preview-dark .preview-badge {
    background: #263238;
    color: #80cbc4;
}

.compact p.compact {
